    <div className="relative w-full h-screen">
      <NavBar/>
      {/* Background Video */}
      <video
        className="w-full h-full object-cover absolute top-0 left-0 z-[-1]"
        src={backgroundVideo}
        loop
        muted
        autoPlay
        ></video>

      {/* Overlay Content */}
      <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-20 z-">
        <h1 className="text-center text-6xl text-white">
          Explore The Wonder Of Solar System
        </h1>
      </div>

